using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class ActorSkeletonGizmoOperations:RefCounted
{
    private readonly ActorSkeletonPoseOperations _pose=new();
    private static Node Spatial(RefCounted owner)=>owner.Get("spatial").As<Node>();private static Node Editor(RefCounted owner)=>Spatial(owner).Get("editor").As<Node>();private static RefCounted Model(RefCounted owner)=>Editor(owner).Get("model").As<RefCounted>();private static Control Gizmo(RefCounted owner)=>Spatial(owner).Get("gizmo").As<Control>();private static Resource Actor(Node rig)=>rig.Get("actor").As<Resource>();private static Skeleton3D Skeleton(Node rig)=>rig.Get("skeleton").As<Skeleton3D>();private static bool Before(RefCounted owner)=>owner.Get("before").AsGodotDictionary().Count>0;
    public Node3D? runtime(RefCounted owner){var node=Spatial(owner).Call("primary").AsGodotObject() as Node3D;var script=node?.GetScript().As<Script>();while(script!=null){if(script.ResourcePath=="res://scripts/actors/examples/ActorSkeletonRigRuntime.cs")return node;script=script.GetBaseScript();}return null;}
    public bool active(RefCounted owner){var rig=runtime(owner);return rig!=null&&Actor(rig).GetMeta("editor_bone_mode",false).AsBool()&&Skeleton(rig).GetBoneCount()>0;}
    public int selected(RefCounted owner){var rig=runtime(owner);return rig!=null?Math.Min(Math.Max(Actor(rig).GetMeta("editor_selected_bone",0).AsInt32(),0),Skeleton(rig).GetBoneCount()-1):-1;}
    public Transform3D transform(RefCounted owner){var skeleton=Skeleton(runtime(owner)!);return skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(selected(owner));}
    public void select_bone(RefCounted owner,int index){var rig=runtime(owner)!;Actor(rig).SetMeta("editor_selected_bone",index);var inspector=Editor(owner).Get("inspector").AsGodotObject();if(GodotObject.IsInstanceValid(inspector))inspector.CallDeferred("_rebuild_selected");Gizmo(owner).QueueRedraw();}
    public Rect2 toolbar_rect(int index)=>new Rect2(248+index*88,10,84,27);
    public void draw(RefCounted owner)
    {
        var rig=runtime(owner);if(rig==null)return;var skeleton=Skeleton(rig);var gizmo=Gizmo(owner);bool mode=Actor(rig).GetMeta("editor_bone_mode",false).AsBool();for(int i=0;i<(mode&&skeleton.GetBoneCount()>0?3:1);i++){var rect=toolbar_rect(i);gizmo.DrawRect(rect,new Color(mode&&i==0?"285c57":"152430"));gizmo.DrawRect(rect,new Color("71d8be"),false,1);gizmo.DrawString(ThemeDB.FallbackFont,rect.Position+new Vector2(6,18),new[]{"Bones  B","◆ Pose  I","↺ Rest"}[i],HorizontalAlignment.Left,78,11,new Color("e3f1f3"));}if(!active(owner))return;var spatial=Spatial(owner);var lens=spatial.Call("camera").As<Camera3D>();for(int i=0;i<skeleton.GetBoneCount();i++){var point=skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(i).Origin;if(lens.IsPositionBehind(point))continue;var screen=spatial.Call("project",point).AsVector2();int parent=skeleton.GetBoneParent(i);var color=new Color(i==selected(owner)?"ffd078":"8bded5");if(parent>=0){var from=skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(parent).Origin;if(!lens.IsPositionBehind(from)){var start=spatial.Call("project",from).AsVector2();gizmo.DrawLine(start,screen,new Color("10212d"),7,true);gizmo.DrawLine(start,screen,color,3,true);}}gizmo.DrawCircle(screen,7,new Color("10212d"));gizmo.DrawCircle(screen,4.5f,color);}gizmo.DrawString(ThemeDB.FallbackFont,new Vector2(12,78),"Bone: "+skeleton.GetBoneName(selected(owner))+" · W/E/R: transform · I: key pose",HorizontalAlignment.Left,-1,12,new Color("ffd078"));
    }
    public int pick(RefCounted owner,Vector2 point,bool jointsOnly)
    {
        var skeleton=Skeleton(runtime(owner)!);var spatial=Spatial(owner);var lens=spatial.Call("camera").As<Camera3D>();float best=12;int result=-1;for(int i=0;i<skeleton.GetBoneCount();i++){var world=skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(i).Origin;if(lens.IsPositionBehind(world))continue;float distance=point.DistanceTo(spatial.Call("project",world).AsVector2());if(distance<best){best=distance;result=i;}}if(result>=0||jointsOnly)return result;for(int i=0;i<skeleton.GetBoneCount();i++){int parent=skeleton.GetBoneParent(i);if(parent<0)continue;var a=skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(parent).Origin;var b=skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(i).Origin;if(lens.IsPositionBehind(a)||lens.IsPositionBehind(b))continue;float distance=point.DistanceTo(Geometry2D.GetClosestPointToSegment(point,spatial.Call("project",a).AsVector2(),spatial.Call("project",b).AsVector2()));if(distance<best){best=distance;result=i;}}return result;
    }
    public bool begin(RefCounted owner){var rig=runtime(owner)!;int bone=selected(owner);string mode=Spatial(owner).Get("mode").AsString(),channel=mode=="move"?"position":mode=="rotate"?"rotation":"scale";owner.Set("drag_rig",rig);owner.Set("drag_bone",bone);owner.Set("channel",channel);var original=_pose.value(Actor(rig),bone,channel);owner.Set("original",original);owner.Set("final",original);owner.Set("before",_pose.capture(Model(owner),Actor(rig)));var skeleton=Skeleton(rig);int parent=skeleton.GetBoneParent(bone);var basis=skeleton.GlobalBasis;if(parent>=0)basis*=skeleton.GetBoneGlobalPose(parent).Basis;owner.Set("parent_basis",basis);owner.Set("selection",Actor(rig).Get("id"));owner.Set("time",Editor(owner).Get("canvas").AsGodotObject().Get("playhead"));Gizmo(owner).GrabFocus();return true;}
    public void update(RefCounted owner,Vector2 point,bool snap)
    {
        var spatial=Spatial(owner);var hit=spatial.Call("_plane_hit",point);if(hit.VariantType==Variant.Type.Nil)return;var delta=hit.AsVector3()-spatial.Get("start_point").AsVector3();var axis=spatial.Get("axis").AsVector3();int drag=spatial.Get("drag_axis").AsInt32();if(drag>=0)delta=axis*delta.Dot(axis);var original=owner.Get("original").AsVector3();var basis=owner.Get("parent_basis").AsBasis();var final=original;switch(spatial.Get("mode").AsString()){case "move":if(snap)delta=delta.Snapped(Vector3.One*.1f);final=original+basis.Inverse()*delta;break;case "rotate":float angle=spatial.Get("start_vector").AsVector3().SignedAngleTo((hit.AsVector3()-spatial.Get("pivot").AsVector3()).Normalized(),axis);if(snap)angle=Mathf.Snapped(angle,Mathf.Pi/12);var localAxis=(basis.Inverse()*axis).Normalized();final=(new Basis(localAxis,angle)*Basis.FromEuler(original*(Mathf.Pi/180))).GetEuler()*(180/Mathf.Pi);break;case "scale":var mouse=spatial.Get("start_mouse").AsVector2();float amount=drag<0?1+(point.X-mouse.X-point.Y+mouse.Y)/140:1+delta.Dot(axis)/spatial.Get("drag_length").AsSingle();if(snap)amount=Mathf.Snapped(amount,.1f);if(drag<0)final*=Math.Max(.01f,amount);else final[drag]*=Math.Max(.01f,amount);break;}owner.Set("final",final);_pose.preview(Model(owner),Actor(owner.Get("drag_rig").As<Node>()),owner.Get("drag_bone").AsInt32(),owner.Get("channel").AsString(),final);
    }
    public void finish(RefCounted owner,bool cancel){if(!Before(owner))return;var before=owner.Get("before").AsGodotDictionary();if(cancel)_pose.restore(Model(owner),before);else _pose.commit(Model(owner),before,owner.Get("drag_bone").AsInt32(),new Settings{[owner.Get("channel")]=owner.Get("final")},false);owner.Set("before",new Settings());owner.Set("drag_rig",default(Variant));}
    public void sync(RefCounted owner){if(!Before(owner))return;var spatial=Spatial(owner);if(!spatial.Call("enabled").AsBool()){finish(owner,true);return;}var actor=Model(owner).Call("selected_actor").As<Resource>();if(actor==null||actor.Get("id").AsString()!=owner.Get("selection").AsString()||selected(owner)!=owner.Get("drag_bone").AsInt32()||!Mathf.IsEqualApprox(owner.Get("time").AsDouble(),Editor(owner).Get("canvas").AsGodotObject().Get("playhead").AsDouble()))finish(owner,true);}
    public void reset(RefCounted owner){var rig=runtime(owner)!;int index=selected(owner);var rest=Skeleton(rig).GetBoneRest(index);_pose.commit(Model(owner),_pose.capture(Model(owner),Actor(rig)),index,new Settings{["position"]=rest.Origin,["rotation"]=rest.Basis.GetRotationQuaternion().GetEuler()*(180/Mathf.Pi),["scale"]=rest.Basis.Scale},false);}
    public bool handle_event(RefCounted owner,InputEvent input)
    {
        if(Before(owner)){if(input is InputEventKey escape&&escape.Pressed&&escape.Keycode==Key.Escape||input is InputEventMouseButton right&&right.Pressed&&right.ButtonIndex==MouseButton.Right){finish(owner,true);return true;}if(input is InputEventMouseMotion motion){update(owner,motion.Position,motion.CtrlPressed);return true;}if(input is InputEventMouseButton release&&release.ButtonIndex==MouseButton.Left&&!release.Pressed){finish(owner,false);return true;}return input is InputEventKey key&&!key.CtrlPressed;}var rig=runtime(owner);if(rig==null||Input.IsMouseButtonPressed(MouseButton.Right))return false;var actor=Actor(rig);var gizmo=Gizmo(owner);if(input is InputEventKey keyEvent&&keyEvent.Pressed&&!keyEvent.Echo&&gizmo.HasFocus()&&!keyEvent.CtrlPressed&&!keyEvent.AltPressed){if(keyEvent.Keycode==Key.B){actor.SetMeta("editor_bone_mode",!actor.GetMeta("editor_bone_mode",false).AsBool());return true;}if(active(owner)&&keyEvent.Keycode==Key.I){_pose.key_pose(Model(owner),actor,selected(owner));return true;}}if(input is not InputEventMouseButton click||click.ButtonIndex!=MouseButton.Left||!click.Pressed)return false;for(int i=0;i<(active(owner)?3:1);i++){if(!toolbar_rect(i).HasPoint(click.Position))continue;if(i==0)actor.SetMeta("editor_bone_mode",!actor.GetMeta("editor_bone_mode",false).AsBool());else if(i==1)_pose.key_pose(Model(owner),actor,selected(owner));else reset(owner);gizmo.GrabFocus();return true;}if(active(owner)){int joint=pick(owner,click.Position,true);if(joint>=0&&joint!=selected(owner)){select_bone(owner,joint);gizmo.GrabFocus();return true;}var spatial=Spatial(owner);if(spatial.Call("handle_at",click.Position,spatial.Call("geometry")).AsInt32()!=-2)return false;int index=pick(owner,click.Position,false);if(index>=0){select_bone(owner,index);gizmo.GrabFocus();return true;}}return false;
    }
}
